package ec.edu.uagraria.prog3; import ec.edu.uagraria.prog3.dominio.Cultivo;import ec.edu.uagraria.prog3.dominio.Insumo;import ec.edu.uagraria.prog3.dominio.Lote;import ec.edu.uagraria.prog3.fabrica.DatosProducto;import ec.edu.uagraria.prog3.fabrica.FabricaProductos;import ec.edu.uagraria.prog3.fabrica.TipoProducto;import ec.edu.uagraria.prog3.reglas.CalculadoraCostos;import ec.edu.uagraria.prog3.reglas.Estrategias; import java.util.List; public class Main {     public static void main(String[] args) {         Cultivo banano = (Cultivo) FabricaProductos.crear(                TipoProducto.BANANO, DatosProducto.deBanano("Cavendish"));         Insumo urea = (Insumo) FabricaProductos.crear(                TipoProducto.INSUMO_RIEGO,                DatosProducto.deInsumo("Urea 50 kg", 12, "saco", 32.50));         Insumo fungicida = (Insumo) FabricaProductos.crear(                TipoProducto.INSUMO_RIEGO,                DatosProducto.deInsumo("Fungicida", 8, "litro", 21.75));         Insumo semilla = (Insumo) FabricaProductos.crear(                TipoProducto.INSUMO_RIEGO,                DatosProducto.deInsumo("Semilla certificada", 1, "lote", 180.00));         Lote lote = new Lote("L-01", banano, 4.0, List.of(urea, fungicida, semilla));         CalculadoraCostos calc = new CalculadoraCostos();         System.out.println("Sin estrategia: " + calc.calcular(lote));         calc.setEstrategia(Estrategias.costoDirecto());        System.out.println("Costo directo: USD "                + calc.calcular(lote).map(CalculadoraCostos::redondear)                .orElseThrow());         calc.setEstrategia(Estrategias.costoConManoDeObra());        System.out.println("Con mano de obra: USD "                + calc.calcular(lote).map(CalculadoraCostos::redondear)                .orElseThrow());         calc.setEstrategia(Estrategias.costoPorHectarea());        System.out.println("Por hectárea: USD "                + calc.calcular(lote).map(CalculadoraCostos::redondear)                .orElseThrow());         calc.setEstrategia(                Estrategias.costoConSubsidioFertilizante(0.20));        System.out.println("Con subsidio: USD "                + calc.calcular(lote).map(CalculadoraCostos::redondear)                .orElseThrow());         calc.setEstrategia(                Estrategias.conIva(Estrategias.costoConManoDeObra()));        System.out.println("Con IVA: USD "                + calc.calcular(lote).map(CalculadoraCostos::redondear)                .orElseThrow());    }}